function makeCounter() {
  let count = 0 // private — only the returned fn can access it
  return () => ++count
}
const next = makeCounter()
next() // 1
next() // 2 — count is still alive after makeCounter returned

function debounce(fn, wait) {
  let timer
  return (...args) => {
    clearTimeout(timer)
    timer = setTimeout(() => fn(...args), wait)
  }
}

const controller = new AbortController()
fetch('/api/search', { signal: controller.signal })
  .catch((err) => {
    if (err.name !== 'AbortError') throw err // aborts are expected
  })
controller.abort() // cancel the in-flight request

